37: 
38:   const [anchorEl, setAnchorEl] = useState(null);
39: 
40:   const currentSelection = () => {
41:     if (location.pathname === `/settings/user/${user.id}`) {
42:       return 'account';
43:     }
44:     if (location.pathname.startsWith('/settings')) {
45:       return 'settings';
46:     }
47:     if (location.pathname.startsWith('/reports')) {
48:       return 'reports';
49:     }
50:     if (location.pathname === '/') {
51:       return 'map';
52:     }
53:     return null;
54:   };
55: 
56:   const handleAccount = () => {
57:     setAnchorEl(null);
58:     navigate(`/settings/user/${user.id}`);
59:   };
60: 
61:   const handleLogout = async () => {
62:     setAnchorEl(null);
63: 
64:     const notificationToken = window.localStorage.getItem('notificationToken');
65:     if (notificationToken && !user.readonly) {
66:       window.localStorage.removeItem('notificationToken');
67:       const tokens = user.attributes.notificationTokens?.split(',') || [];
68:       if (tokens.includes(notificationToken)) {
69:         const updatedUser = {
70:           ...user,
71:           attributes: {
72:             ...user.attributes,
73:             notificationTokens:
74:               tokens.length > 1
75:                 ? tokens.filter((it) => it !== notificationToken).join(',')
76:                 : undefined,
77:           },
78:         };
79:         await fetch(`/api/users/${user.id}`, {
80:           method: 'PUT',
81:           headers: { 'Content-Type': 'application/json' },
82:           body: JSON.stringify(updatedUser),
83:         });
84:       }
85:     }
86: 
87:     await fetch('/api/session', { method: 'DELETE' });
88:     nativePostMessage('logout');
89:     navigate('/login');
90:     dispatch(sessionActions.updateUser(null));
91:   };
92: 
93:   const handleSelection = (event, value) => {
94:     switch (value) {
95:       case 'map':
96:         navigate('/');
97:         break;
98:       case 'reports': {
99:         let id = selectedDeviceId;
100:         if (id == null) {
101:           const deviceIds = Object.keys(devices);
102:           if (deviceIds.length === 1) {
103:             id = deviceIds[0];
104:           }
105:         }
106: 
107:         if (id != null) {
108:           navigate(`/reports/combined?deviceId=${id}`);
109:         } else {
110:           navigate('/reports/combined');
111:         }
112:         break;
113:       }
114:       case 'settings':
115:         navigate('/settings/preferences?menu=true');
116:         break;
117:       case 'account':
118:         setAnchorEl(event.currentTarget);
119:         break;
120:       case 'logout':
121:         handleLogout();
122:         break;
123:       default:
124:         break;
125:     }
126:   };
127: 
128:   return (
129:     <Paper square elevation={3}>
130:       <BottomNavigation value={currentSelection()} onChange={handleSelection} showLabels>
131:         <BottomNavigationAction
132:           label={t('mapTitle')}
133:           icon={
134:             <Badge color="error" variant="dot" overlap="circular" invisible={socket !== false}>
135:               <MapIcon />
136:             </Badge>
137:           }
138:           value="map"
139:         />
140:         {!disableReports && (
141:           <BottomNavigationAction
142:             label={t('reportTitle')}
143:             icon={<DescriptionIcon />}
144:             value="reports"
145:           />
146:         )}
147:         {!readonly && (
148:           <BottomNavigationAction
149:             label={t('settingsTitle')}
150:             icon={<SettingsIcon />}
151:             value="settings"
152:           />
153:         )}
154:         {readonly ? (
155:           <BottomNavigationAction
156:             label={t('loginLogout')}
157:             icon={<ExitToAppIcon />}
158:             value="logout"
159:           />
160:         ) : (
161:           <BottomNavigationAction label={t('settingsUser')} icon={<PersonIcon />} value="account" />
162:         )}
163:       </BottomNavigation>
164:       <Menu anchorEl={anchorEl} open={Boolean(anchorEl)} onClose={() => setAnchorEl(null)}>
165:         <MenuItem onClick={handleAccount}>
166:           <Typography color="textPrimary">{t('settingsUser')}</Typography>
167:         </MenuItem>
168:         <MenuItem onClick={handleLogout}>
169:           <Typography color="error">{t('loginLogout')}</Typography>
170:         </MenuItem>
171:       </Menu>
172:     </Paper>
173:   );
174: };
