1: import { useId, useEffect } from 'react';
2: import { map } from './MapView';
3: 
4: const emptyFeatureCollection = { type: 'FeatureCollection', features: [] };
5: 
6: const useMapLayer = ({ source, layers, layersDeps, data, dataDeps = [] }) => {
7:   const id = useId();
8: 
9:   useEffect(() => {
10:     const isGeoJson = !source?.type || source.type === 'geojson';
11:     map.addSource(
12:       id,
13:       isGeoJson ? { type: 'geojson', data: data ?? emptyFeatureCollection, ...source } : source,
14:     );
15:     layers.forEach((layer) => {
16:       const { on, key, ...spec } = layer;
17:       const layerId = key ? `${id}-${key}` : id;
18:       map.addLayer({ ...spec, id: layerId, source: id });
19:       if (on) {
20:         Object.entries(on).forEach(([type, listener]) => map.on(type, layerId, listener));
21:       }
22:     });
23:     return () => {
24:       layers.forEach((layer) => {
25:         const { on, key } = layer;
26:         const layerId = key ? `${id}-${key}` : id;
27:         if (on) {
28:           Object.entries(on).forEach(([type, listener]) => map.off(type, layerId, listener));
29:         }
30:         if (map.getLayer(layerId)) {
31:           map.removeLayer(layerId);
32:         }
33:       });
34:       if (map.getSource(id)) {
35:         map.removeSource(id);
36:       }
37:     };
38:     // eslint-disable-next-line @eslint-react/exhaustive-deps
39:   }, [id, ...layersDeps]);
40: 
41:   useEffect(() => {
42:     if (data !== undefined) {
43:       map.getSource(id)?.setData(data ?? emptyFeatureCollection);
44:     }
45:     // eslint-disable-next-line @eslint-react/exhaustive-deps
46:   }, [id, ...dataDeps]);
47: 
48:   return id;
49: };
50: 
51: export default useMapLayer;
