1: import { sessionActions } from './session';
2: import { devicesActions } from './devices';
3: 
4: const threshold = 3; // per second
5: const minInterval = 1500;
6: const maxInterval = 30000;
7: const scaleFactor = 1000;
8: 
9: // eslint-disable-next-line no-undef
10: const debugMode = process.env.NODE_ENV === 'development';
11: const debugLog = (message) => debugMode && console.log(message);
12: 
13: export default () => (next) => {
14:   const buffer = [];
15:   let throttled = false;
16:   let counter = 0;
17:   let currentInterval = minInterval;
18: 
19:   const tick = () => {
20:     if (throttled) {
21:       const start = performance.now();
22: 
23:       const flushed = buffer.splice(0, buffer.length);
24: 
25:       const deviceUpdates = {};
26:       const positionUpdates = {};
27: 
28:       flushed.forEach((action) => {
29:         if (action.type === devicesActions.update.type) {
30:           action.payload.forEach((item) => (deviceUpdates[item.id] = item));
31:         } else if (action.type === sessionActions.updatePositions.type) {
32:           action.payload.forEach((item) => (positionUpdates[item.deviceId] = item));
33:         }
34:       });
35: 
36:       const mergedDeviceUpdates = Object.values(deviceUpdates);
37:       if (mergedDeviceUpdates.length) {
38:         next({ type: devicesActions.update.type, payload: mergedDeviceUpdates });
39:       }
40: 
41:       const mergedPositionUpdates = Object.values(positionUpdates);
42:       if (mergedPositionUpdates.length) {
43:         next({ type: sessionActions.updatePositions.type, payload: mergedPositionUpdates });
44:       }
45: 
46:       const totalTime = performance.now() - start;
47:       debugLog(
48:         `Flushed ${mergedDeviceUpdates.length + mergedPositionUpdates.length} / ${flushed.length} events in ${totalTime.toFixed(2)} ms`,
49:       );
50:       currentInterval = Math.min(Math.max(totalTime * scaleFactor, minInterval), maxInterval);
51:     }
52: 
53:     const shouldThrottle = (counter * 1000) / currentInterval > threshold;
54:     if (throttled != shouldThrottle) {
55:       debugLog(`Throttling ${shouldThrottle}`);
56:       throttled = shouldThrottle;
57:     }
58:     counter = 0;
59:     if (!throttled) currentInterval = minInterval;
60:     setTimeout(tick, currentInterval);
61:   };
62: 
63:   setTimeout(tick, currentInterval);
64: 
65:   return (action) => {
66:     if (
67:       action.type !== devicesActions.update.type &&
68:       action.type !== sessionActions.updatePositions.type
69:     ) {
70:       return next(action);
71:     }
72: 
73:     counter += 1;
74: 
75:     if (throttled) {
76:       buffer.push(action);
77:       return;
78:     }
79: 
80:     if ((counter * 1000) / currentInterval > threshold) {
81:       if (!throttled) debugLog(`Throttling started`);
82:       throttled = true;
83:     }
84: 
85:     return next(action);
86:   };
87: };
