10:         ? coordinates.map(([longitude, latitude]) => toMapCoordinates(longitude, latitude))
11:         : positions.map((item) => toMapCoordinates(item.longitude, item.latitude));
12:       if (coords.length) {
13:         const bounds = coords.reduce(
14:           (bounds, item) => bounds.extend(item),
