23:     } else {
24:       map.jumpTo({
25:         center: toMapCoordinates(longitude, latitude),
26:         zoom: Math.max(map.getZoom(), 10),
27:       });
28:     }
29:   }, [latitude, longitude, positions, coordinates]);
30: 
31:   return null;
32: };
