1: import { useEffect, useRef, useState } from 'react';
2: 
3: const listeners = new Map();
4: 
5: const broadcast = (key, value) => {
6:   listeners.get(key)?.forEach((listener) => listener(value));
7: };
8: 
9: export const savePersistedState = (key, value) => {
10:   window.localStorage.setItem(key, JSON.stringify(value));
11:   broadcast(key, value);
12: };
13: 
14: export default (key, defaultValue) => {
15:   const defaultRef = useRef(defaultValue);
16: 
17:   const [value, setValue] = useState(() => {
18:     const stickyValue = window.localStorage.getItem(key);
19:     return stickyValue ? JSON.parse(stickyValue) : defaultRef.current;
20:   });
21: 
22:   useEffect(() => {
23:     if (!listeners.has(key)) {
24:       listeners.set(key, new Set());
25:     }
26:     listeners.get(key).add(setValue);
27:     return () => listeners.get(key).delete(setValue);
28:   }, [key]);
29: 
30:   useEffect(() => {
31:     if (value !== defaultRef.current) {
32:       window.localStorage.setItem(key, JSON.stringify(value));
33:     } else {
34:       window.localStorage.removeItem(key);
35:     }
36:     broadcast(key, value);
37:   }, [key, value]);
38: 
39:   return [value, setValue];
40: };
